#[test]
fn energy_state_fixed_native_projection_and_sparse_plan_frames_fit4096(){
 macro_rules! projection{($($kind:ty),*)=>{$(let(d,heap)=observe(<$kind as SnapshotProjection>::projection_birth_demand);assert_eq!(heap,(0,0));assert!(d.copy_bytes<=4096,"{} actual projection frame={d:?}",stringify!($kind));eprintln!("[DEBUG] Energy {} original projection frame copy={}",stringify!($kind),d.copy_bytes);)*};}
 projection!(EnergyModelState,ModelIdentityState,ModelGeometryState,ModelMaterialState,ModelLoadState,ModelControlState,ModelSystemState,ModelGenerationState,ModelOutputState,StateScheduleSet,StateZone,StateSurface,StateFenestration,StateInfiltration);
 macro_rules! sparse{($($fields:ty),*)=>{$(let bytes=std::mem::size_of::<$fields>()+std::mem::size_of::<Option<$fields>>()+std::mem::size_of::<usize>()+std::mem::size_of::<u8>();assert!(bytes<=4096,"{} actual shared sparse frame copy={bytes}",stringify!($fields));eprintln!("[DEBUG] Energy {} original sparse plan frame copy={bytes}",stringify!($fields));)*};}
 sparse!(diff::state_zone_fields::Fields,diff::state_fenestration_fields::Fields,diff::state_infiltration_fields::Fields);
}
#[test]
fn energy_state_original_zone_receive_projection_and_inverse_preserve_paid_authority(){
 let law=corpus();let whole=receive::<EnergyModelState>(&law["model"]);assert_portable_value(semio_framework_value::ToValue::to_value(&whole),&law["model"]);assert_eq!(whole.geometry.get().zones.len(),1);assert_eq!(whole.identity.get().name.get(),law["model"]["name"].as_str().unwrap());drain(whole);for refusal in law["refusals"].as_array().unwrap(){let original=source(receive::<StateZone>(&law["cases"][1]["before"]["zones"][0]));let mut post=project_zone(&original);let pointer=post.name.get().as_ptr();let identity=post.name.identity();let patch=source(receive::<diff::StateZonePatch>(&refusal["patch"]));assert!(!central_zone(&patch,&original,&mut post));assert_eq!(post.as_ref(),original.borrow().get());assert_eq!(post.name.get().as_ptr(),pointer);assert_eq!(post.name.identity(),identity);drain(patch);drain(post);drain(original);}for case in law["cases"].as_array().unwrap().iter().filter(|case|case["id"]=="zone-label"||case["id"]=="zone-volume"){
  let operation=&case["forward"][0];let path=operation["path"].as_str().unwrap().split('/').collect::<Vec<_>>();let rank=path[2].parse::<usize>().unwrap();let original=source(receive::<StateZone>(&case["before"]["zones"][rank]));let base=original.borrow();let pointer=base.get().name.get().as_ptr();let original_identity=base.get().name.identity();
  let d=StateZone::projection_birth_demand();let(mut cursor,_)=StateZone::begin_projection(grant(d)).unwrap();for _ in 0..100000{if cursor.ready(){break;}let g=grant(cursor.demands(original.borrow(),4096).unwrap());let(step,heap)=observe(||cursor.advance(original.borrow(),4096,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(cursor.ready());let g=grant(cursor.take_demand().unwrap());let(mut post,p)=cursor.take(g).unwrap().unwrap();assert!(p.fits(g));assert_eq!(post.name.identity(),original_identity);assert_eq!(post.name.get().as_ptr(),pointer);cursor.begin_close();for _ in 0..100000{if cursor.terminal_is_empty(){break;}let g=grant(cursor.close_demands(4096).unwrap());let(step,heap)=observe(||cursor.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(cursor.terminal_is_empty());
  let field=path[3];let mut patch=serde_json::Map::new();patch.insert(field.to_owned(),operation["value"].clone());let authored=source(receive::<diff::StateZonePatch>(&serde_json::Value::Object(patch)));let mut inverse=diff::state_zone_fields::Fields::new(RetainedPatchSource::Inverse);for _ in 0..100000{let g=grant(inverse.demand(authored.borrow(),original.borrow(),4096).unwrap());let(step,heap)=observe(||inverse.advance(authored.borrow(),original.borrow(),4096,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));if matches!(step,RetainedCloneStep::Complete(_)){break;}}
  let g=grant(RetirementDemand{copy_bytes:std::mem::size_of::<diff::StateZonePatch>()*2,depth:1,..Default::default()});let(undo,p)=inverse.take(g).unwrap();assert!(p.fits(g));let undo=undo.unwrap();if field=="name"{assert_eq!(undo.name.as_ref().unwrap().get(),case["inverse"][0]["value"].as_str().unwrap());assert_eq!(undo.name.as_ref().unwrap().identity(),original_identity);}else{assert_eq!(undo.volume_m3,case["inverse"][0]["value"].as_f64());assert!(undo.name.is_none());}inverse.begin_close();for _ in 0..100000{if inverse.terminal_is_empty(){break;}let g=grant(inverse.close_demand(4096).unwrap());let(step,heap)=observe(||inverse.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(inverse.terminal_is_empty());assert_eq!(original.borrow().get().name.get().as_ptr(),pointer);assert!(central_zone(&authored,&original,&mut post));assert_eq!(post.id,original.borrow().get().id);if field=="name"{assert_eq!(post.name.get(),case["after"]["zones"][rank]["name"].as_str().unwrap());}else{assert_eq!(post.volume_m3,case["after"]["zones"][rank]["volume_m3"].as_f64().unwrap());assert_eq!(post.name.identity(),original_identity);}let changed=projected_source(post);let mut restored=project_zone(&changed);let undo=source(undo);assert!(central_zone(&undo,&changed,&mut restored));assert_eq!(restored.as_ref(),original.borrow().get());assert_eq!(restored.name.identity(),original_identity);drain(restored);drain(undo);drain(authored);drain(changed);drain(original);eprintln!("[DEBUG] Energy original {:?} native receiving/projection/inverse preserves actual name authority and exact paid allocations",case["id"]);
 }
}

fn project_zone<A:RetireOwned+Sync>(original:&RetainedCloneSource<StateZone,A>)->Box<StateZone>{
 let d=StateZone::projection_birth_demand();let(mut cursor,_)=StateZone::begin_projection(grant(d)).unwrap();for _ in 0..100000{if cursor.ready(){break;}let g=grant(cursor.demands(original.borrow(),4096).unwrap());let(step,heap)=observe(||cursor.advance(original.borrow(),4096,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(cursor.ready());let g=grant(cursor.take_demand().unwrap());let((post,p),heap)=observe(||cursor.take(g).unwrap().unwrap());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));cursor.begin_close();for _ in 0..100000{if cursor.terminal_is_empty(){break;}let g=grant(cursor.close_demands(4096).unwrap());let(step,heap)=observe(||cursor.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(cursor.terminal_is_empty());post
}
fn central_zone<A:RetireOwned+Sync>(patch:&RetainedCloneSource<diff::StateZonePatch>,original:&RetainedCloneSource<StateZone,A>,post:&mut StateZone)->bool{central_fragment(patch,original.borrow(),post)}






fn seal_projected<T:RetireOwned+Sync>(value:Box<T>)->SealedShared<T>{let d=RetirementDemand{copy_bytes:2*std::mem::size_of::<T>()+2*std::mem::size_of::<SealedShared<T>>(),capacity_bytes:SealedShared::<T>::birth_bytes(),release_bytes:std::mem::size_of::<T>(),depth:1};let g=grant(d);let(result,h)=observe(||SealedShared::admit(*value,semio_framework_value::shared_issuance::SharedIssuer::owned(),g).unwrap_or_else(|_|panic!("funded original branch sealing")));assert_eq!(h,(result.1.retained_capacity_bytes,d.release_bytes));result.0}
#[test]
fn energy_native_sparse_zone_path_rebuilds_only_its_pages_and_branch_and_restores_original_inverse_authority(){
 use semio_framework_value_persistent::list::persistent::PersistentSet;
 for case in corpus()["cases"].as_array().unwrap().iter().filter(|case|case["id"]=="zone-label"||case["id"]=="zone-volume"){
  let law=corpus();let mut model=law["model"].clone();model["zones"]=case["before"]["zones"].clone();let rank=case["forward"][0]["path"].as_str().unwrap().split('/').nth(2).unwrap().parse::<usize>().unwrap();let original=source(receive::<EnergyModelState>(&model));let base=original.borrow();let geometry=base.project(1,|m|m.geometry.get());let zones=geometry.project(0,|g|&g.zones);let q=grant(zones.get().rank_observation_demand(rank).unwrap());let((zone,p),h)=observe(||PersistentList::observe_rank(zones,rank,q).unwrap().unwrap());assert!(p.fits(q));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));
  let mut row=project_record(zone);let field=case["forward"][0]["path"].as_str().unwrap().rsplit('/').next().unwrap();let patch=source(receive::<diff::StateZonePatch>(&serde_json::json!({field:case["forward"][0]["value"]})));assert!(central_fragment(&patch,zone,&mut row));let row=source(seal_projected(row));let mut set=PersistentSet::new(rank);for _ in 0..100000{if set.output_ready(){break;}let d=set.demand(zones,row.borrow()).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||set.advance(zones,row.borrow(),denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));}let(s,h)=observe(||set.advance(zones,row.borrow(),g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(set.output_ready());let g=grant(set.take_demand().unwrap());let((next,p),h)=observe(||set.take(g).unwrap().unwrap());assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));set.begin_close();for _ in 0..100000{if set.terminal_is_empty(){break;}let g=grant(set.close_demand(4096).unwrap());let(s,h)=observe(||set.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(set.terminal_is_empty());
  let mut next_geometry=project_record(geometry);let previous=std::mem::replace(&mut next_geometry.zones,next);let authored=source(diff::EnergyModelStatePatch{geometry:Some(seal_projected(next_geometry)),..Default::default()});let mut post=project_record(base);assert!(central_fragment(&authored,base,&mut post));assert_ne!(post.geometry.identity(),base.get().geometry.identity());if rank>0{assert_eq!(std::ptr::from_ref(post.geometry.get().zones.get(0).unwrap()),std::ptr::from_ref(base.get().geometry.get().zones.get(0).unwrap()));}assert_eq!(post.identity.identity(),base.get().identity.identity());assert_eq!(post.materials.identity(),base.get().materials.identity());assert_eq!(post.loads.identity(),base.get().loads.identity());assert_eq!(post.controls.identity(),base.get().controls.identity());assert_eq!(post.systems.identity(),base.get().systems.identity());assert_eq!(post.generation.identity(),base.get().generation.identity());assert_eq!(post.outputs.identity(),base.get().outputs.identity());assert_portable_value(post.geometry.get().zones.get(rank).unwrap().to_value(),&case["after"]["zones"][rank]);
  let mut inverse=diff::energy_model_fields::Fields::new(RetainedPatchSource::Inverse);for _ in 0..100000{let g=grant(inverse.demand(authored.borrow(),base,4096).unwrap());let(s,h)=observe(||inverse.advance(authored.borrow(),base,4096,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedCloneStep::Complete(_)){break;}}let g=grant(RetirementDemand{copy_bytes:2*std::mem::size_of::<diff::EnergyModelStatePatch>(),depth:1,..Default::default()});let(undo,p)=inverse.take(g).unwrap();assert!(p.fits(g));let undo=undo.unwrap();assert_eq!(undo.geometry.as_ref().unwrap().identity(),base.get().geometry.identity());inverse.begin_close();for _ in 0..100000{if inverse.terminal_is_empty(){break;}let g=grant(inverse.close_demand(4096).unwrap());let(s,h)=observe(||inverse.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(inverse.terminal_is_empty());let changed=projected_source(post);let mut restored=project_record(changed.borrow());let undo=source(undo);assert!(central_fragment(&undo,changed.borrow(),&mut restored));assert_eq!(restored.geometry.identity(),base.get().geometry.identity());assert_portable_value(restored.to_value(),&model);drain(restored);drain(undo);drain(changed);drain(authored);drain(previous);drain(row);drain(patch);drain(original);
 }
}
fn central_zone(patch:&RetainedCloneSource<diff::StateZonePatch>,original:&RetainedCloneSource<StateZone>,post:&mut PostFixture<StateZone>)->bool{
 use protocol::mutation::retained::{begin_retained_diff,retained_diff_birth_demand,preflight_retained_diff,commit_retained_diff,RetainedDiffPreflightStep};
 let d=retained_diff_birth_demand::<StateZone,diff::StateZonePatch>();let g=grant(d);let((mut owner,p),heap)=observe(||begin_retained_diff::<StateZone,diff::StateZonePatch>(g).unwrap());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);let mut admitted=None;
 for _ in 0..100000{let d=owner.preflight_demand(patch.borrow(),original.borrow(),post.borrow(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(step,heap)=observe(||preflight_retained_diff(&mut owner,patch.borrow(),original.borrow(),post.borrow(),4096,denied,&mut control).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.preflight_demand(patch.borrow(),original.borrow(),post.borrow(),4096).unwrap(),d);}let(step,heap)=observe(||preflight_retained_diff(&mut owner,patch.borrow(),original.borrow(),post.borrow(),4096,g,&mut control).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));match step{RetainedDiffPreflightStep::Admitted(_,messages)=>{assert!(messages.is_empty());admitted=Some(true);break;},RetainedDiffPreflightStep::Refused(_,messages)=>{assert!(messages.is_empty());admitted=Some(false);break;},_=>{}}}
 let admitted=admitted.expect("original central Zone preflight settles");if admitted{owner.inverse_admission(patch.borrow(),original.borrow()).unwrap();let mut complete=false;for _ in 0..100000{let d=owner.commit_demand(patch.borrow(),original.borrow(),post.mutable_read(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(step,heap)=observe(||commit_retained_diff(&mut owner,patch.borrow(),original.borrow(),post,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.commit_demand(patch.borrow(),original.borrow(),post.borrow(),4096).unwrap(),d);}let(step,heap)=observe(||commit_retained_diff(&mut owner,patch.borrow(),original.borrow(),post,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));if matches!(step,RetainedCloneStep::Complete(_)){complete=true;break;}}assert!(complete);}
 owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(step,heap)=observe(||owner.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.close_demand(4096).unwrap(),d);}let(step,heap)=observe(||owner.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(owner.terminal_is_empty());admitted
}
